-- Spec 004 Completion, assignments and progress (specs/004-progress-assignments/data-model.md ›
-- Migration). Generated by `prisma migrate diff` (the column and the three indexes), then completed by
-- hand: checks, a partial unique index, one helper function, replaced policies, bucket limits and the
-- Realtime publication, which Prisma can't express. Nothing SQL-only is dropped except the policies
-- replaced on purpose below (research.md R11).

-- AlterTable: the planned length of a focus session (FR-007). study_sessions was empty on dev when
-- this was written (tasks.md T002), so no default is needed.
ALTER TABLE "study_sessions" ADD COLUMN     "planned_minutes" SMALLINT NOT NULL;

-- CreateIndex
CREATE INDEX "lesson_progress_student_completed" ON "lesson_progress"("student_id", "completed_at");

-- CreateIndex
CREATE INDEX "comments_thread" ON "comments"("student_id", "target_type", "target_id", "created_at");

-- CreateIndex
CREATE INDEX "study_sessions_student_started" ON "study_sessions"("student_id", "started_at");

-- ── 1. Focus sessions: 15 or 25 minutes, never counted past their length (research.md R3) ───────
alter table public.study_sessions
  add constraint study_sessions_planned check (planned_minutes in (15, 25)),
  add constraint study_sessions_capped
    check (ended_at is null or ended_at <= started_at + planned_minutes * interval '1 minute');

-- ── 2. One running session per student ─────────────────────────────────────────────────────
create unique index study_sessions_one_running on public.study_sessions (student_id)
  where ended_at is null;

-- ── 3. The Admin's lesson rule, once (mirrors requireAdminLessonTarget in guards.ts) ────────────
-- A Published, non-deleted lesson in a course the caller owns, a student linked to them, and an
-- active assignment of that course for the student. Used by the progress and comment policies.
create or replace function public.admin_lesson_target(p_lesson uuid, p_student uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select is_admin_of(p_student)
     and exists (select 1
                 from lessons l
                 join courses c on c.id = l.course_id
                 join course_assignments a on a.course_id = l.course_id
                 where l.id = p_lesson
                   and c.owner_id = auth.uid()
                   and l.status = 'published'
                   and l.deleted_at is null
                   and a.student_id = p_student
                   and a.status = 'active');
$$;

-- ── 4. Policies replaced so both layers apply the same rules (research.md R11) ───────────────────
-- lesson_progress: 0_init let a student write any row of theirs (any completed_by) and gave the
-- Admin UPDATE only. Now: the student writes rows for lessons they can read, with completed_by null
-- or themselves; the Admin inserts and updates for admin_lesson_target with completed_by null or
-- themselves. Nobody deletes (undo and reopen are updates).
drop policy progress_student on public.lesson_progress;
create policy progress_student_read on public.lesson_progress for select
  using (student_id = auth.uid());
create policy progress_student_insert on public.lesson_progress for insert
  with check (student_id = auth.uid()
              and can_read_lesson(lesson_id)
              and (completed_by is null or completed_by = auth.uid()));
create policy progress_student_update on public.lesson_progress for update
  using (student_id = auth.uid())
  with check (student_id = auth.uid()
              and can_read_lesson(lesson_id)
              and (completed_by is null or completed_by = auth.uid()));

drop policy progress_admin_write on public.lesson_progress;
create policy progress_admin_insert on public.lesson_progress for insert
  with check (admin_lesson_target(lesson_id, student_id)
              and (completed_by is null or completed_by = auth.uid()));
create policy progress_admin_update on public.lesson_progress for update
  using (admin_lesson_target(lesson_id, student_id))
  with check (admin_lesson_target(lesson_id, student_id)
              and (completed_by is null or completed_by = auth.uid()));

-- submissions: 0_init let a student set any status (even reviewed) and the Admin update any row of
-- a linked student. Now the transitions of data-model.md › Submission: the student creates and edits
-- only while draft or needs_redo and can only save or submit; the Admin reviews only non-Draft
-- work on lessons of their own courses (requireSubmissionReviewer). subs_admin_read is unchanged.
drop policy subs_student on public.submissions;
create policy subs_student_read on public.submissions for select
  using (student_id = auth.uid());
create policy subs_student_insert on public.submissions for insert
  with check (student_id = auth.uid()
              and can_read_lesson(lesson_id)
              and status in ('draft', 'submitted')
              and reviewed_at is null);
create policy subs_student_update on public.submissions for update
  using (student_id = auth.uid() and status in ('draft', 'needs_redo'))
  with check (student_id = auth.uid()
              and can_read_lesson(lesson_id)
              and status in ('draft', 'needs_redo', 'submitted')
              and (status <> 'submitted' or reviewed_at is null));

drop policy subs_admin_review on public.submissions;
create policy subs_admin_review on public.submissions for update
  using (status <> 'draft'
         and is_admin_of(student_id)
         and exists (select 1 from lessons l
                     where l.id = submissions.lesson_id and owns_course(l.course_id)))
  with check (status in ('reviewed', 'needs_redo')
              and is_admin_of(student_id)
              and exists (select 1 from lessons l
                          where l.id = submissions.lesson_id and owns_course(l.course_id)));

-- comments: the target must belong to the thread (spec FR-010). Notes: a lesson the student can
-- read (personal courses included, like requireLessonReader) or, for the Admin, admin_lesson_target.
-- Review comments: only the Admin, on a non-Draft submission of that student in their own course.
drop policy comments_write on public.comments;
create policy comments_write on public.comments for insert
  with check (
    author_id = auth.uid()
    and (
      (target_type = 'lesson'
       and ((student_id = auth.uid() and can_read_lesson(target_id))
            or admin_lesson_target(target_id, student_id)))
      or (target_type = 'submission'
          and is_admin_of(student_id)
          and exists (select 1
                      from submissions s
                      join lessons l on l.id = s.lesson_id
                      where s.id = comments.target_id
                        and s.student_id = comments.student_id
                        and s.status <> 'draft'
                        and owns_course(l.course_id)))));

-- Storage, bucket `submissions`, paths <student_id>/<lesson_id>/<file>: uuid_folder() never throws
-- on other buckets' paths (002). The Admin reads a file only when that lesson's submission isn't a
-- Draft, like subs_admin_read.
drop policy submission_files_rw on storage.objects;
create policy submission_files_rw on storage.objects for all
  using (bucket_id = 'submissions' and public.uuid_folder(name, 1) = auth.uid())
  with check (bucket_id = 'submissions' and public.uuid_folder(name, 1) = auth.uid());

drop policy submission_files_admin_read on storage.objects;
create policy submission_files_admin_read on storage.objects for select
  using (bucket_id = 'submissions'
         and is_admin_of(public.uuid_folder(name, 1))
         and exists (select 1 from public.submissions s
                     where s.student_id = public.uuid_folder(name, 1)
                       and s.lesson_id = public.uuid_folder(name, 2)
                       and s.status <> 'draft'));

-- ── 5. Bucket limits (FR-003, research.md R7): resized images, 2 MB each ──────────────────────────
update storage.buckets
set file_size_limit = 2097152,
    allowed_mime_types = array['image/webp', 'image/jpeg']
where id = 'submissions';

-- ── 6. Realtime (FR-009, SC-002, research.md R10): subscribers get rows their SELECT policies allow
alter publication supabase_realtime
  add table public.submissions, public.comments, public.lesson_progress;
